      "max": 40,
      "comment": "Thanks and coming are covered, but «Що принести» is not marked as a question and lacks a subject, so the third point is only partly done."
    },
    {
      "id": "form",
      "score": 5,
      "max": 10,
      "comment": "A greeting is present, but there is no sign-off and the register is abrupt."
    },
    {
      "id": "norms",
      "score": 14,
      "max": 40,
      "comment": "«Спасибі» and «приглашення» are Russianisms (surzhyk); the correct forms are «Дякую» and «запрошення». Missing question mark."
    },
    {
      "id": "volume",
      "score": 5,
      "max": 10,
      "comment": "Only about 8 words, under the 10-word minimum."
    }
  ],
  "corrected": "Привіт! Дякую за запрошення. Я прийду. Що принести?",
  "changes": [
    {
      "before": "Спасибі",
      "after": "Дякую",
      "explanation": "Surzhyk: Ukrainian uses «дякую» (or «дякуємо»); «спасибі» is a Russian calque."
    },
    {
      "before": "приглашення",
      "after": "запрошення",
      "explanation": "Russianism: the Ukrainian noun is «запрошення» (from запросити)."
    },
    {
      "before": "Що принести",
      "after": "Що принести?",
      "explanation": "A question needs a question mark."
    }
  ],
  "tips": [
    "Replace Russian-looking words with their Ukrainian pair: спасибі → дякую.",
    "End with a short friendly sign-off such as «До зустрічі!»."
  ]
}
